window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d344e8e6da4389e0"]={"versions": [{"id": "FIG-d344e8e6da4389e0", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Datenflussdiagramm zur Einbettung des FlexRay Transportprotokolls (FrTp) in den AUTOSAR-Kommunikationsstack. Dargestellt ist die vertikale Schichtung auf Sender- und Empfängerseite (Peer-to-Peer-Kommunikation) zwischen dem PDU-Router (PduR), dem FrTp und der FlexRay-Schnittstelle (FrIf) sowie die Zuordnung der Dateneinheiten (SDU, PDU, PCI) über einen physikalischen FlexRay-Bus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>PduR (PDU Router)</strong>: Oberhalb des FrTp angeordnete Schicht; übergibt die Sendedaten bzw. empfängt die zusammengesetzten Nutzdaten als <code>Fr N-SDU</code>.</li>\n<li><strong>FrTp (FlexRay Transport Protocol)</strong>: Zentrale Vermittlungs- und Segmentierungsschicht. Enthält intern die Elemente <code>Fr N-PCI</code> (Protocol Control Information), <code>Fr N-SDU (Part)</code> (Nutzdatenfragment) und die daraus gebildete bzw. zerlegte <code>Fr N-PDU</code>.</li>\n<li><strong>FrIf (FlexRay Interface)</strong>: Unterhalb des FrTp angeordnete Schnittstelle zur FlexRay-Hardware; tauscht Daten mit FrTp auf Verbindungsschichtebene als <code>Fr L-SDU</code> aus und ist über eine gestrichelte Linie an den FlexRay-Bus angebunden.</li>\n<li><strong>Dateneinheiten</strong>:</li>\n<li><code>Fr N-SDU</code>: Service Data Unit des Transportprotokolls (orangefarbene Boxen zwischen PduR und FrTp).</li>\n<li><code>Fr N-PDU</code>: Protocol Data Unit des Transportprotokolls (grüne Box zwischen Sender- und Empfänger-FrTp sowie weiße Blöcke innerhalb der FrTp-Module).</li>\n<li><code>Fr N-PCI</code>: Steuerdaten des Transportprotokolls.</li>\n<li><code>Fr L-SDU</code>: Service Data Unit der Sicherungsschicht (Data Link Layer / FrIf).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Sendepfad (Sender / linke Spalte)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>Fr N-SDU</code> wird vom oberen Layer <code>PduR</code> an <code>FrTp</code> übergeben.</li>\n<li><code>FrTp</code> führt eine Segmentierung durch: Ein Nutzdatenfragment <code>Fr N-SDU (Part)</code> wird mit der <code>Fr N-PCI</code> zu einer <code>Fr N-PDU</code> zusammengefügt.</li>\n<li>Die resultierende <code>Fr N-PDU</code> wird als <code>Fr L-SDU</code> an die darunterliegende Schicht <code>FrIf</code> weitergereicht.</li>\n<li><code>FrIf</code> überträgt die Frames über den FlexRay-Bus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Übertragung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die logische Peer-to-Peer-Übertragung zwischen den Transportprotokoll-Entitäten erfolgt als <code>Fr N-PDU</code> (gestrichelte Verbindungslinie).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Empfangspfad (Empfänger / rechte Spalte)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>FrIf</code> empfängt Daten vom Bus und übergibt sie als <code>Fr L-SDU</code> an <code>FrTp</code>.</li>\n<li><code>FrTp</code> extrahiert aus der empfangenen <code>Fr N-PDU</code> die Steuerinformation <code>Fr N-PCI</code> sowie das Datenfragment <code>Fr N-SDU (Part)</code>.</li>\n<li>Nach Zusammensetzen der Fragmente wird die vollständige <code>Fr N-SDU</code> an den <code>PduR</code> übergeben.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die AUTOSAR-Standardterminologie für den Datenaustausch und die Segmentierung/Reassemblierung im FrTp-Modul:</p>\n<ul class=\"fig-list\">\n<li><code>Fr N-SDU</code> entspricht der PduR-seitigen Schnittstelle (z. B. Bereitstellung via Buffer-Handling / <code>FrTp_Transmit</code>).</li>\n<li><code>Fr L-SDU</code> und <code>Fr N-PDU</code> sind strukturell identisch in Bezug auf die Datenübertragung zwischen FrTp und FrIf (<code>FrIf_Transmit</code> / <code>FrIf_RxIndication</code>).</li>\n<li>Für die Implementierung ist sicherzustellen, dass Header-Informationen (<code>Fr N-PCI</code>) exakt den FrTp-Paketformaten (SF, FF, CF, FC) entsprechen und das Puffer-Handling zur Fragmentierung/Zusammensetzung von <code>Fr N-SDU (Part)</code> konform zu den AUTOSAR-FrTp-Anforderungen ausgelegt wird.</li>\n</ul>"}, {"id": "FIG-490efee72ab3aae5", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Datenflussdiagramm zur Einbettung des FlexRay Transportprotokolls (FrTp) in den AUTOSAR-Kommunikationsstack. Dargestellt ist die vertikale Schichtung auf Sender- und Empfängerseite (Peer-to-Peer-Kommunikation) zwischen dem PDU-Router (PduR), dem FrTp und der FlexRay-Schnittstelle (FrIf) sowie die Zuordnung der Dateneinheiten (SDU, PDU, PCI) über einen physikalischen FlexRay-Bus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>PduR (PDU Router)</strong>: Oberhalb des FrTp angeordnete Schicht; übergibt die Sendedaten bzw. empfängt die zusammengesetzten Nutzdaten als <code>Fr N-SDU</code>.</li>\n<li><strong>FrTp (FlexRay Transport Protocol)</strong>: Zentrale Vermittlungs- und Segmentierungsschicht. Enthält intern die Elemente <code>Fr N-PCI</code> (Protocol Control Information), <code>Fr N-SDU (Part)</code> (Nutzdatenfragment) und die daraus gebildete bzw. zerlegte <code>Fr N-PDU</code>.</li>\n<li><strong>FrIf (FlexRay Interface)</strong>: Unterhalb des FrTp angeordnete Schnittstelle zur FlexRay-Hardware; tauscht Daten mit FrTp auf Verbindungsschichtebene als <code>Fr L-SDU</code> aus und ist über eine gestrichelte Linie an den FlexRay-Bus angebunden.</li>\n<li><strong>Dateneinheiten</strong>:</li>\n<li><code>Fr N-SDU</code>: Service Data Unit des Transportprotokolls (orangefarbene Boxen zwischen PduR und FrTp).</li>\n<li><code>Fr N-PDU</code>: Protocol Data Unit des Transportprotokolls (grüne Box zwischen Sender- und Empfänger-FrTp sowie weiße Blöcke innerhalb der FrTp-Module).</li>\n<li><code>Fr N-PCI</code>: Steuerdaten des Transportprotokolls.</li>\n<li><code>Fr L-SDU</code>: Service Data Unit der Sicherungsschicht (Data Link Layer / FrIf).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Sendepfad (Sender / linke Spalte)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>Fr N-SDU</code> wird vom oberen Layer <code>PduR</code> an <code>FrTp</code> übergeben.</li>\n<li><code>FrTp</code> führt eine Segmentierung durch: Ein Nutzdatenfragment <code>Fr N-SDU (Part)</code> wird mit der <code>Fr N-PCI</code> zu einer <code>Fr N-PDU</code> zusammengefügt.</li>\n<li>Die resultierende <code>Fr N-PDU</code> wird als <code>Fr L-SDU</code> an die darunterliegende Schicht <code>FrIf</code> weitergereicht.</li>\n<li><code>FrIf</code> überträgt die Frames über den FlexRay-Bus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Übertragung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die logische Peer-to-Peer-Übertragung zwischen den Transportprotokoll-Entitäten erfolgt als <code>Fr N-PDU</code> (gestrichelte Verbindungslinie).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Empfangspfad (Empfänger / rechte Spalte)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>FrIf</code> empfängt Daten vom Bus und übergibt sie als <code>Fr L-SDU</code> an <code>FrTp</code>.</li>\n<li><code>FrTp</code> extrahiert aus der empfangenen <code>Fr N-PDU</code> die Steuerinformation <code>Fr N-PCI</code> sowie das Datenfragment <code>Fr N-SDU (Part)</code>.</li>\n<li>Nach Zusammensetzen der Fragmente wird die vollständige <code>Fr N-SDU</code> an den <code>PduR</code> übergeben.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die AUTOSAR-Standardterminologie für den Datenaustausch und die Segmentierung/Reassemblierung im FrTp-Modul:</p>\n<ul class=\"fig-list\">\n<li><code>Fr N-SDU</code> entspricht der PduR-seitigen Schnittstelle (z. B. Bereitstellung via Buffer-Handling / <code>FrTp_Transmit</code>).</li>\n<li><code>Fr L-SDU</code> und <code>Fr N-PDU</code> sind strukturell identisch in Bezug auf die Datenübertragung zwischen FrTp und FrIf (<code>FrIf_Transmit</code> / <code>FrIf_RxIndication</code>).</li>\n<li>Für die Implementierung ist sicherzustellen, dass Header-Informationen (<code>Fr N-PCI</code>) exakt den FrTp-Paketformaten (SF, FF, CF, FC) entsprechen und das Puffer-Handling zur Fragmentierung/Zusammensetzung von <code>Fr N-SDU (Part)</code> konform zu den AUTOSAR-FrTp-Anforderungen ausgelegt wird.</li>\n</ul>"}], "trans": [{"from": "FIG-d344e8e6da4389e0", "to": "FIG-490efee72ab3aae5", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
